describe("doctests of sympy.utilities.lambdify", () => {
  // argument type TFModuleWrapper
  //   tf.compat.v1.enable_eager_execution()
  //   => None
  it.todo("tf.compat.v1.enable_eager_execution()");
  it("lambdastr(x, x**2)", () => {
    const x = new Sym('x');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(lambdastr(x, pow(x, 2)))).toBe('lambda x: (x**2)');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("lambdastr((x,y,z), [z,y,x])", () => {
    const [x, y, z] = symbols('x y z');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(lambdastr([x, y, z], [z, y, x]))).toBe('lambda x,y,z: ([z, y, x])');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("lambdastr((x, (y, z)), x + y)", () => {
    const [x, y, z] = symbols('x y z');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(lambdastr([x, [y, z]], add(x, y)))).toBe('lambda _0,_1: (lambda x,y,z: (x + y))(_0,_1[0],_1[1])');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
});

